package ma.fstt.dao;
import ma.fstt.model.*; import ma.fstt.persistence.JPAUtil; import java.util.*;
public class CommandeDAO extends BaseDAO { public void valider(Long clientId,Map<Long,Integer> panier){tx(em->{Client c=em.find(Client.class,clientId);if(c==null||panier==null||panier.isEmpty())throw new IllegalArgumentException("Client invalide ou panier vide.");Commande cmd=new Commande(c);for(var x:panier.entrySet()){Produit p=em.find(Produit.class,x.getKey());int q=x.getValue();if(p==null||q<1||p.getStock()<q)throw new IllegalStateException("Stock insuffisant pour le produit "+x.getKey());p.setStock(p.getStock()-q);cmd.ajouterLigne(new LigneCommande(p,q,p.getPrix()));}em.persist(cmd);});} public List<Commande> toutes(){try(var em=JPAUtil.getEmf().createEntityManager()){return em.createQuery("SELECT DISTINCT c FROM Commande c JOIN FETCH c.client LEFT JOIN FETCH c.lignes l LEFT JOIN FETCH l.produit ORDER BY c.id DESC",Commande.class).getResultList();}} }